function loadTipsContent(){const n=document.getElementById("tips-content");if(!n){console.error("Content container not found");return}if(typeof DOMPurify>"u"||typeof DOMPurify.sanitize!="function"){n.textContent=t("Tips temporarily unavailable. Please refresh the page."),console.error("DOMPurify unavailable \u2014 refusing to render unsanitized content");return}fetch("/tips/content").then(e=>{if(!e.ok)throw new Error("Failed to load tips content: Network response was not OK");return e.text()}).then(e=>{n.innerHTML=DOMPurify.sanitize(e)}).catch(e=>{n.textContent=t("Tips temporarily unavailable. Please refresh the page."),console.error("Error loading tips content:",e)})}window.loadTipsContent=loadTipsContent;
